using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Auditing;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.ContentItems.RestoreContentRevision;public sealed class RestoreContentRevisionCommandHandler(IContentItemRepository repo,IContentAuditService audit,IContentCacheService cache,IUnitOfWork uow):ICommandHandler<RestoreContentRevisionCommand,Result>{public async Task<Result> HandleAsync(RestoreContentRevisionCommand c,CancellationToken ct=default){var x=await repo.GetByIdWithDetailsAsync(c.ContentId,ct);if(x is null||x.IsDeleted)return Result.Failure(ContentErrors.ContentNotFound);var revision=await repo.GetRevisionAsync(c.ContentId,c.RevisionId,ct);if(revision is null)return Result.Failure(ContentErrors.RevisionNotFound);var before=ContentAuditSnapshots.From(x);x.CreateRevision(c.ActorUserId,c.Reason??"before-restore");x.RestoreRevision(revision,c.ActorUserId);await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.ContentRevisionRestored,ContentAuditActions.Restored,ContentAuditEntityTypes.ContentItem,x.Id,c.ActorUserId,Before:before,After:ContentAuditSnapshots.From(x),Payload:new{c.RevisionId,c.Reason}),ct);await uow.SaveChangesAsync(ct);await cache.RemoveContentAsync(x.SiteKey,x.Slug,ct);return Result.Success();}}
